-- Synthetic V3 native test fixture, captured from docs/v3-native-results.json; no production user data.
PRAGMA foreign_keys=OFF;
CREATE TABLE migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE scenes(id TEXT PRIMARY KEY, name TEXT NOT NULL, enabled INTEGER NOT NULL, sort_order INTEGER NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE tasks(id TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('web','app','folder')), enabled INTEGER NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE scene_tasks(id TEXT PRIMARY KEY, scene_id TEXT NOT NULL REFERENCES scenes(id) ON DELETE CASCADE, task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, sort_order INTEGER NOT NULL, UNIQUE(scene_id,task_id));
CREATE INDEX scene_order ON scene_tasks(scene_id,sort_order);
CREATE TABLE schedules(id TEXT PRIMARY KEY, scene_id TEXT NOT NULL REFERENCES scenes(id) ON DELETE CASCADE, trigger_type TEXT NOT NULL, enabled INTEGER NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE INDEX schedule_enabled ON schedules(enabled,scene_id);
CREATE TABLE settings(key TEXT PRIMARY KEY, value_json TEXT NOT NULL CHECK(json_valid(value_json)));
CREATE TABLE execution_runs(id TEXT PRIMARY KEY, scene_id TEXT, scene_name_snapshot TEXT NOT NULL, trigger_type TEXT NOT NULL, rule_id TEXT, started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL, local_run_date TEXT NOT NULL);
CREATE INDEX runs_date ON execution_runs(started_at DESC);
CREATE TABLE execution_logs(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES execution_runs(id) ON DELETE CASCADE, task_id TEXT NOT NULL, task_name_snapshot TEXT NOT NULL, started_at TEXT, finished_at TEXT, status TEXT NOT NULL, message TEXT NOT NULL);
CREATE INDEX logs_run ON execution_logs(run_id);
CREATE TABLE automatic_claims(scene_id TEXT NOT NULL, local_date TEXT NOT NULL, rule_id TEXT NOT NULL, claimed_at TEXT NOT NULL, PRIMARY KEY(scene_id,local_date));
CREATE TABLE rule_history(rule_id TEXT NOT NULL, local_date TEXT NOT NULL, triggered_at TEXT NOT NULL, PRIMARY KEY(rule_id,local_date));
CREATE TABLE workflows(id TEXT PRIMARY KEY,scene_id TEXT NOT NULL REFERENCES scenes(id) ON DELETE CASCADE,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE INDEX workflows_scene ON workflows(scene_id);
CREATE TABLE workflow_nodes(id TEXT PRIMARY KEY,workflow_id TEXT NOT NULL REFERENCES workflows(id) ON DELETE CASCADE,node_type TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE INDEX nodes_workflow ON workflow_nodes(workflow_id);
CREATE TABLE workflow_edges(id TEXT PRIMARY KEY,workflow_id TEXT NOT NULL REFERENCES workflows(id) ON DELETE CASCADE,source_node_id TEXT NOT NULL REFERENCES workflow_nodes(id) ON DELETE CASCADE,target_node_id TEXT NOT NULL REFERENCES workflow_nodes(id) ON DELETE CASCADE,source_handle TEXT NOT NULL);
CREATE TABLE scene_workflows(scene_id TEXT PRIMARY KEY REFERENCES scenes(id) ON DELETE CASCADE,workflow_id TEXT NOT NULL REFERENCES workflows(id) ON DELETE CASCADE);
CREATE TABLE window_layouts(id TEXT PRIMARY KEY,scene_id TEXT REFERENCES scenes(id) ON DELETE SET NULL,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE window_layout_items(id TEXT PRIMARY KEY,layout_id TEXT NOT NULL REFERENCES window_layouts(id) ON DELETE CASCADE,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE shortcuts(id TEXT PRIMARY KEY,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE workflow_templates(id TEXT PRIMARY KEY,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE backup_records(id TEXT PRIMARY KEY,filename TEXT NOT NULL UNIQUE,backup_type TEXT NOT NULL,created_at TEXT NOT NULL,size INTEGER NOT NULL,status TEXT NOT NULL);
CREATE TABLE workflow_runs(run_id TEXT PRIMARY KEY REFERENCES execution_runs(id) ON DELETE CASCADE,workflow_id TEXT NOT NULL,name TEXT NOT NULL);
CREATE TABLE workflow_execution_logs(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES execution_runs(id) ON DELETE CASCADE,node_id TEXT NOT NULL,node_name TEXT NOT NULL,node_type TEXT NOT NULL,started_at TEXT,finished_at TEXT,status TEXT NOT NULL,result_json TEXT NOT NULL CHECK(json_valid(result_json)),error_message TEXT NOT NULL);
CREATE INDEX workflow_logs_run ON workflow_execution_logs(run_id);
CREATE TABLE workspace_modes(id TEXT PRIMARY KEY,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE environment_rules(id TEXT PRIMARY KEY,mode_id TEXT REFERENCES workspace_modes(id) ON DELETE RESTRICT,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE environment_snapshots(id TEXT PRIMARY KEY,captured_at TEXT NOT NULL,schema_version INTEGER NOT NULL,context_json TEXT NOT NULL CHECK(json_valid(context_json)));
CREATE INDEX environment_snapshot_date ON environment_snapshots(captured_at);
CREATE TABLE automation_events(id TEXT PRIMARY KEY,event_key TEXT NOT NULL UNIQUE,event_type TEXT NOT NULL,occurred_at TEXT NOT NULL,status TEXT NOT NULL);
CREATE INDEX automation_event_date ON automation_events(occurred_at);
CREATE TABLE automation_event_claims(event_key TEXT PRIMARY KEY,claimed_at TEXT NOT NULL);
CREATE TABLE automation_config_versions(id TEXT PRIMARY KEY,config_json TEXT NOT NULL UNIQUE CHECK(json_valid(config_json)));
CREATE TABLE automation_evaluations(event_id TEXT PRIMARY KEY REFERENCES automation_events(id) ON DELETE CASCADE,config_id TEXT NOT NULL REFERENCES automation_config_versions(id),event_json TEXT NOT NULL CHECK(json_valid(event_json)),inputs_json TEXT NOT NULL CHECK(json_valid(inputs_json)));
CREATE TABLE automation_decisions(id TEXT PRIMARY KEY,event_id TEXT REFERENCES automation_events(id) ON DELETE CASCADE,rule_id TEXT REFERENCES environment_rules(id) ON DELETE SET NULL,snapshot_id TEXT REFERENCES environment_snapshots(id) ON DELETE SET NULL,evaluated_at TEXT NOT NULL,status TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE INDEX automation_decision_date ON automation_decisions(evaluated_at DESC);
CREATE INDEX automation_decision_rule ON automation_decisions(rule_id,evaluated_at DESC);
CREATE TABLE automation_rule_state(rule_id TEXT PRIMARY KEY REFERENCES environment_rules(id) ON DELETE CASCADE,last_action_at TEXT NOT NULL);
CREATE TABLE automation_overrides(id TEXT PRIMARY KEY,mode_id TEXT NOT NULL REFERENCES workspace_modes(id) ON DELETE CASCADE,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE ai_configuration_drafts(id TEXT PRIMARY KEY,created_at TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)));
PRAGMA foreign_keys=ON;
